import{z as B,x as h,o as e,c as s,q as E,j as l,D as t,d as r,s as o,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"空中像与对比度","description":"","frontmatter":{"title":"空中像与对比度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/aerial-image-contrast.md","filePath":"litho/aerial-image-contrast.md","lastUpdated":1791413859000}'),p={name:"litho/aerial-image-contrast.md"};function A(C,a,d,I,c,_){const m=h("Mermaid");return e(),s("div",null,[a[2]||(a[2]=E('<h1 id="空中像与对比度" tabindex="-1">空中像与对比度 <a class="header-anchor" href="#空中像与对比度" aria-label="Permalink to &quot;空中像与对比度&quot;">​</a></h1><div class="epigraph"><p>空中像是晶圆表面（或胶层指定平面）上的光学强度分布；对比度问的是这张灰度图还够不够被胶切成稳定的线。</p><footer>—— 据 Mack, Fundamental Principles of Optical Lithography 对 aerial image 与 image contrast 的定义整理</footer></div><p><a href="/litho/hopkins-tcc">上一课</a>（Hopkins TCC）。给出部分相干与 TCC，强度原则上可以算。缺口是：还没有把「算出来的 \\(I(x,y)\\)」命名为空中像，也没有规定产线用哪一个标量来读它好不好印。本课钉空中像与对比度（以及 NILS）。对比度怎么换成剂量标尺、NILS 与 ILS 如何分工，留给<a href="/litho/nils-ils">下一课</a>；焦深如何把这张图沿轴毁掉，是后面的<a href="/litho/depth-of-focus">焦深与瑞利焦深</a>一课。胶如何把强度变成溶速，是抗蚀剂课的缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TCC 积分的结果是位置上的强度 \\(I(x,y)\\)，单位是功率密度。光学工程师优化的对象就是这张图，不是显影后的 SEM。若直接跳到 CD，会把胶阈值、扩散和刻蚀偏置都算进镜头。缺口因此是：先承认空中像是光学链的输出，再定义它的调制有多深。</p><p>密线栅上最常用的标量是对比度</p> \\[C=\\frac{I_\\mathrm{max}-I_\\mathrm{min}}{I_\\mathrm{max}+I_\\mathrm{min}}. \\]<p>\\(C=0\\) 表示只剩零级，胶无论多陡都切不出线；\\(C\\) 接近 1 表示暗区足够黑。孤立线、孔、二维拐角没有单一的 \\(I_\\mathrm{max}/I_\\mathrm{min}\\)，还需要边缘斜率。</p><p><span class="marginnote">数字实例：\\(I_\\mathrm{max}=1.0\\)、\\(I_\\mathrm{min}=0.1\\) 时 \\(C=(1-0.1)/(1+0.1)\\approx 0.82\\)；若暗区只压到 \\(I_\\mathrm{min}=0.5\\)，同样亮峰下 \\(C\\approx 0.33\\)——底一灰，阈值上下一点点剂量就能让线宽大幅摆动。</span></p><h3 id="对比度不是胶的-γ" tabindex="-1">对比度不是胶的 γ <a class="header-anchor" href="#对比度不是胶的-γ" aria-label="Permalink to &quot;对比度不是胶的 γ&quot;">​</a></h3><p>\\(C\\) 是光学强度的性质。胶的衬度 \\(\\gamma\\) 是显影速率对剂量的陡度，上一课序里还不存在——本课不要借用化学名词。空中像对比不够，再陡的胶也只是把噪声一起切锐；空中像对比很高，钝胶仍可能印出可用 CD。两个旋钮后课会相乘，本课只写光学这一个。</p><p><span class="marginnote">空中像可以定义在空气/水与胶的界面，也可以沿胶厚做层切。薄胶近似用一张二维 \\(I(x,y)\\)；厚胶或高 NA 要沿 \\(z\\) 取样。本课默认指定平面上的二维强度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对节距 \\(p\\) 的线栅，在最佳焦距取一条垂直于线的剖线，读 \\(I_\\mathrm{max}\\) 与 \\(I_\\mathrm{min}\\)，得 \\(C(p)\\)。\\(C\\) 随 \\(p\\) 下降的那条曲线，就是「这个照明 + 这个 \\(\\mathrm{NA}\\) + 这张掩模」的光学可印窗口。部分相干改变的是 \\(C(p)\\) 的形状：圆照明与环形照明的峰值节距不同。</p><p>边缘更敏感的量是对数斜率。归一化影像对数斜率</p> \\[\\mathrm{NILS}=\\mathrm{CD}\\cdot\\frac{d\\ln I}{dx}\\Big|_{\\mathrm{threshold}} \\]<p>把斜率乘到目标线宽上，使不同 CD 可以比较。NILS 高，剂量误差引起的 CD 变化小。Mack 把 NILS 当作空中像与工艺窗口之间的桥梁：还没有胶模型时，先看 NILS 够不够。</p><p><span class="marginnote">直觉类比：把空中像剖线想成一条山路，NILS 就是「爬到阈值高度那一段」的陡峭程度——坡越陡，脚下踩偏一步（剂量抖一点）高度变化越小，切出来的线宽越稳。</span></p><h3 id="阈值模型是临时接口" tabindex="-1">阈值模型是临时接口 <a class="header-anchor" href="#阈值模型是临时接口" aria-label="Permalink to &quot;阈值模型是临时接口&quot;">​</a></h3><p>最粗的抗蚀剂模型是：强度高于 \\(I_\\mathrm{th}\\) 的地方显影掉（正胶）。CD 就是 \\(I(x)=I_\\mathrm{th}\\) 的两个根之间的距离。本课允许这个接口，只为了让对比度有一个「能不能切」的几何意思；酸扩散与真显影曲线禁止在这里展开。</p><p><span class="marginnote">不要把模拟器里的 aerial image 和 SEM 上的线宽叫同一个「像」。前者是 \\(I(x,y)\\)，后者已经过潜像与显影。OPC 若只拟合 SEM 而不校准空中像，光学与化学会缠死。</span></p>',21)),(e(),l(n,null,{default:t(()=>[o(m,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCC%5B%22%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%20TCC%22%5D%20--%3E%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20I(x%2Cy)%22%5D%0A%20%20I%20--%3E%20C%5B%22%E5%AF%B9%E6%AF%94%E5%BA%A6%20C%22%5D%0A%20%20I%20--%3E%20NILS%5B%22NILS%22%5D%0A%20%20C%20--%3E%20PW%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%A6%BB%E7%84%A6%E5%90%8E%20C%20%E4%BB%8D%E5%A4%9F%E5%90%A6%22%5D%0A%20%20NILS%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%E5%88%87%20CD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"空中像是衍射级在像面的干涉图样，再对源点做强度积分。两束成像给出近余弦的调制，对比度由两束振幅比决定；三束成像多一个零级偏置，\\(I_\\mathrm{min}\\) 抬高，\\(C\\) 下降。这就是为什么低 \\(k_1\\) 必须动照明或相移去压零级——机制在空中像上已经可见，不必等到 RET 目录。",-1)),(e(),l(n,null,{default:t(()=>[o(m,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20B2%5B%22%E4%B8%A4%E6%9D%9F%E6%88%90%E5%83%8F%EF%BC%9A%C2%B11%20%E7%BA%A7%22%5D%20--%3E%20COS%5B%22%E8%BF%91%E4%BD%99%E5%BC%A6%E8%B0%83%E5%88%B6%22%5D%0A%20%20COS%20--%3E%20HIC%5B%22Imin%20%E5%A4%9F%E6%9A%97%EF%BC%9AC%20%E9%AB%98%22%5D%0A%20%20B3%5B%22%E4%B8%89%E6%9D%9F%E6%88%90%E5%83%8F%EF%BC%9A%E9%9B%B6%E7%BA%A7%20%2B%20%C2%B11%20%E7%BA%A7%22%5D%20--%3E%20DC%5B%22%E9%9B%B6%E7%BA%A7%E6%8A%AC%E5%BA%95%EF%BC%9AImin%20%E5%8F%98%E4%BA%AE%22%5D%0A%20%20DC%20--%3E%20LOC%5B%22C%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LOC%20--%3E%20RET%5B%22%E5%8E%8B%E9%9B%B6%E7%BA%A7%EF%BC%9A%E7%A6%BB%E8%BD%B4%E7%85%A7%E6%98%8E%20%2F%20%E7%9B%B8%E7%A7%BB%22%5D%0A%20%20DENSE%5B%22%E8%8A%82%E8%B7%9D%E5%8F%98%E5%AF%86%22%5D%20--%3E%20OUT%5B%22%E4%B8%80%E7%BA%A7%E5%87%BA%E7%9E%B3%EF%BC%9A%E5%8F%AA%E5%89%A9%E9%9B%B6%E7%BA%A7%22%5D%0A%20%20OUT%20--%3E%20C0%5B%22C%20%3D%200%EF%BC%9A%E5%88%87%E4%B8%8D%E5%87%BA%E7%BA%BF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p>散焦还没写公式，但机制已清楚：光瞳里的二次相位让各级相对延迟改变，余弦调制变浅，\\(C\\) 与 NILS 一起掉。本课只在最佳焦距定义 \\(C\\) 与 NILS，把轴向扫描留给焦深课。</p><h3 id="矢量修正会改-i-而不是改定义" tabindex="-1">矢量修正会改 I 而不是改定义 <a class="header-anchor" href="#矢量修正会改-i-而不是改定义" aria-label="Permalink to &quot;矢量修正会改 I 而不是改定义&quot;">​</a></h3><p>高 NA 下 TM 分量干涉变差，\\(I_\\mathrm{min}\\) 上升，标量对比度过于乐观。定义本身不变：仍是指定平面上的 \\(|E|^2\\) 或坡印廷通量的约定投影。后课把 \\(I\\) 升级成矢量能量沉积；对比度公式不用改写。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>空中像不含套刻，也不含 flare 的长程散射——杂散光会给 \\(I\\) 加一层缓变底座，使全场 \\(C\\) 下降，那是计量课的缺口。本课的 \\(C\\) 与 NILS 是局部、理想光学的量。也不要把「对比度 70%」直接写成可量产：量产看的是曝光–散焦窗口里 CD 是否落在规格内，中间还隔着胶。</p><p>后课默认：说到空中像就是 \\(I(x,y)\\)；说到光学对比度就是 \\(C\\) 或 NILS，不再与胶的 \\(\\gamma\\) 混名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>空中像是指定平面上的光学强度 \\(I(x,y)\\)，是光学链的输出。</li><li>线栅用 \\(C=(I_\\mathrm{max}-I_\\mathrm{min})/(I_\\mathrm{max}+I_\\mathrm{min})\\)；边缘用 NILS。</li><li>\\(C\\) 不是胶衬度 \\(\\gamma\\)；阈值切 CD 只是临时接口。</li><li>低调制来自零级偏置或丢失衍射级，机制已在空中像上可见。</li><li>本课在最佳焦距定义对比；NILS 与 ILS 是下一课，离焦随后。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Goodman 对像面强度的傅里叶光学表述。</li></ul>',8))])}const S=B(p,[["render",A]]);export{f as __pageData,S as default};
